typedef void *vm_entity_t;

struct entity_list_iterator
{
  vm_entity_t *current;
};

struct entity_list
{
  vm_entity_t *start;
  vm_entity_t *finish;
  vm_entity_t *end_of_storage;
  entity_list_iterator begin() { entity_list_iterator i = { start }; return i; }
};

typedef entity_list *vm_entity_list_t;
typedef entity_list_iterator vm_entity_list_iterator_t;

class vm_stack
{
public:
  int salloc;
  char *buffer;
  char *SP;
  void *my_thread;
  char *get_SP() const { return SP; }
  void pop(int n) { SP -= n; }
  bool push(const char *src, int n);
};

void error(const char *message);

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
  protected:
    char *name;
  public:
    function(script_library_class *slc, const char *n);
    virtual ~function();
    virtual bool operator()(vm_stack& stack, entry_t entry) { return true; }
  };
};

#define SLF_PARMS \
  stack.pop(sizeof(parms_t)); \
  parms_t* parms = (parms_t*)stack.get_SP()
#define SLF_RETURN \
  if (!stack.push((char*)&result,sizeof(result))) \
    error("script stack overflow")
#define SLF_DONE return true

class slf_entity_list_begin_t : public script_library_class::function
  {
  public:
    slf_entity_list_begin_t(script_library_class* slc,const char* n) : script_library_class::function(slc,n) {}
    struct parms_t
      {
      vm_entity_list_t me;
      };
    virtual bool operator()(vm_stack& stack,entry_t entry)
      {
      SLF_PARMS;
      vm_entity_list_iterator_t result = parms->me->begin();
      SLF_RETURN;
      SLF_DONE;
      }
  };
